function createOrchestratorAgent(model, customPrompt, customAppendPrompt, disabledAgents, excludeDescriptions, waitForUserEnabled = true, wakeSchedulerEnabled = true, hostFlavor) {
  const basePrompt = buildOrchestratorPrompt(disabledAgents, excludeDescriptions, waitForUserEnabled, wakeSchedulerEnabled, hostFlavor);
  const prompt = resolvePrompt("orchestrator", undefined, customPrompt, basePrompt, customAppendPrompt);
  const definition = {
    name: "orchestrator",
    description: "AI coding orchestrator that delegates tasks to specialist agents for optimal quality, speed, and cost",
    config: {
      prompt
    }
  };
  if (Array.isArray(model)) {
    definition._modelArray = model.map((m) => typeof m === "string" ? { id: m } : m);
  } else if (typeof model === "string" && model) {
    definition.config.model = model;
  }
  return definition;
}

